  "_source_pk" text NOT NULL,
  "_row_hash" text NOT NULL,
  "_dump_id" text NOT NULL,
  "_loaded_at" timestamptz NOT NULL DEFAULT now(),
  "id" text,
  "cronname" text,
  "execute_timeint" text,
  "runtime" text,
  PRIMARY KEY ("_dump_id", "_row_no")
);
CREATE INDEX IF NOT EXISTS "stg_cron_run_history_pk_idx" ON "migration"."stg_cron_run_history" ("_source_pk");

CREATE TABLE IF NOT EXISTS "migration"."stg_site_activity_logs" (
  "_row_no" integer NOT NULL,
  "_source_pk" text NOT NULL,
  "_row_hash" text NOT NULL,
  "_dump_id" text NOT NULL,
  "_loaded_at" timestamptz NOT NULL DEFAULT now(),
  "id" text,
  "row_id" text,
  "table_name" text,
  "log_type" text,
  "user_id" text,
  "log_date" text,
  "php_filename" text,
  "section" text,
  "notes_comments" text,
  PRIMARY KEY ("_dump_id", "_row_no")
);
CREATE INDEX IF NOT EXISTS "stg_site_activity_logs_pk_idx" ON "migration"."stg_site_activity_logs" ("_source_pk");

